INSERT INTO reviews (id, review_assignment_id, overall_comment, total_score, submitted_at) VALUES
('f4000000-4000-4000-8000-000000000001', 'f3000000-4000-4000-8000-000000000001', 'Nhóm làm bài rất chỉn chu, code backend chia layer chuẩn, giao diện đẹp có đủ responsive.', 9.20, NOW() - INTERVAL '1 day'),
('f4000000-4000-4000-8000-000000000002', 'f3000000-4000-4000-8000-000000000002', 'Bài làm hoàn thiện đầy đủ chức năng nhưng tài liệu README còn hơi sơ sài.', 8.50, NOW() - INTERVAL '1 day'),
('f4000000-4000-4000-8000-000000000003', 'f3000000-4000-4000-8000-000000000003', 'Chức năng ổn, tuy nhiên API giỏ hàng còn thiếu try-catch nên có thể bị crash server.', 7.80, NOW() - INTERVAL '12 hours'),
('f4000000-4000-4000-8000-000000000005', 'f3000000-4000-4000-8000-000000000005', 'Bài nộp đúng hạn, code chạy được nhưng thiếu trang admin quản lý sản phẩm.', 7.50, NOW() - INTERVAL '8 hours'),
('f4000000-4000-4000-8000-000000000006', 'f3000000-4000-4000-8000-000000000006', 'Nhóm làm xuất sắc, có tích hợp đính kèm file và xác thực JWT chặt chẽ.', 9.50, NOW() - INTERVAL '5 hours'),
('f4000000-4000-4000-8000-000000000007', 'f3000000-4000-4000-8000-000000000007', 'Thiết kế CSDL hợp lý, giao diện giỏ hàng mượt mà nhưng bài viết tóm tắt cần dài hơn.', 8.80, NOW() - INTERVAL '1 day'),
('f4000000-4000-4000-8000-000000000008', 'f3000000-4000-4000-8000-000000000008', 'Cấu trúc bài nộp khá ổn, giao diện có responsive cơ bản.', 8.00, NOW() - INTERVAL '18 hours'),
('f4000000-4000-4000-8000-000000000009', 'f3000000-4000-4000-8000-000000000009', 'Chức năng tìm kiếm sản phẩm hoạt động tốt, API xử lý nhanh.', 8.20, NOW() - INTERVAL '14 hours'),
('f4000000-4000-4000-8000-000000000011', 'f3000000-4000-4000-8000-000000000011', 'Cần bổ sung thêm phần xác thực đầu vào Zod ở phía Backend.', 8.10, NOW() - INTERVAL '7 hours'),
('f4000000-4000-4000-8000-000000000012', 'f3000000-4000-4000-8000-000000000012', 'Ấn tượng với phần thiết kế giao diện sáng tạo của nhóm.', 9.00, NOW() - INTERVAL '4 hours')
